l12 = [
 U(1, "river", "Three periods|তিনিটা সময়", "Read the Assam Accord's date boundaries.|অসম চুক্তিৰ তাৰিখৰ সীমা পঢ়া।",
   "Finding recorded: the dates 1 January 1966 and 25 March 1971 divide three groups.|প্ৰমাণ লিখা হ'ল: ১৯৬৬ৰ ১ জানুৱাৰী আৰু ১৯৭১ৰ ২৫ মাৰ্চে তিনিটা গোট ভাগ কৰে।",
   ["The Assam Accord was signed on 15 August 1985|১৯৮৫ৰ ১৫ আগষ্টত অসম চুক্তি স্বাক্ষৰিত হয়", "Section 6A of the Citizenship Act implements it|নাগৰিকত্ব আইনৰ ধাৰা ৬ক-এ ইয়াক কাৰ্যকৰী কৰে", "Arrivals before 1 January 1966 are one group|১৯৬৬ৰ ১ জানুৱাৰীৰ আগত অহাসকল এটা গোট", "On or after 25 March 1971 is another|১৯৭১ৰ ২৫ মাৰ্চ বা পিছত অহাসকল আন এটা গোট"],
   S("A rule only for Assam|কেৱল অসমৰ নিয়ম", "The <mark>Assam Accord</mark> of 15 August 1985 ended the Assam Movement. Section 6A of the Citizenship Act carried its citizenship terms into law.|১৯৮৫ৰ ১৫ আগষ্টৰ <mark>অসম চুক্তিয়ে</mark> অসম আন্দোলনৰ অন্ত পেলালে। নাগৰিকত্ব আইনৰ ধাৰা ৬ক-এ ইয়াৰ চৰ্ত আইনত ৰাখিলে।", art="seal"),
   S("Three periods, three rules|তিনিটা সময়, তিনিটা নিয়ম", "Before <mark>1 January 1966</mark>. From then through <mark>24 March 1971</mark>. On or after <mark>25 March 1971</mark>. Each period is treated differently.|<mark>১৯৬৬ৰ ১ জানুৱাৰীৰ</mark> আগত। তাৰ পৰা <mark>১৯৭১ৰ ২৪ মাৰ্চলৈ</mark>। <mark>১৯৭১ৰ ২৫ মাৰ্চ</mark> বা পিছত। প্ৰতিটো সময়ৰ ব্যৱস্থা বেলেগ।", "These dates concern a legal framework, not any one person's status.|এই তাৰিখ আইনী কাঠামোৰ, কোনো ব্যক্তিৰ স্থিতিৰ নহয়।", art="calendar"),
   IN("The Assam Accord was signed in|অসম চুক্তি স্বাক্ষৰিত হৈছিল", ".|চনত।", ["1971|১৯৭১", "1985|১৯৮৫", "2019|২০১৯"], 1, "On 15 August 1985.|১৯৮৫ৰ ১৫ আগষ্টত।"),
   OR("Put the periods in order.|সময়বোৰ ক্ৰমত সজোৱা।", ["Before 1 January 1966|১৯৬৬ৰ ১ জানুৱাৰীৰ আগত", "1 January 1966 to 24 March 1971|১৯৬৬ৰ ১ জানুৱাৰীৰ পৰা ১৯৭১ৰ ২৪ মাৰ্চ", "From 25 March 1971|১৯৭১ৰ ২৫ মাৰ্চৰ পৰা"], "Three periods.|তিনিটা সময়।"),
   TF("Section 6A applies across all Indian States.|ধাৰা ৬ক ভাৰতৰ সকলো ৰাজ্যত প্ৰযোজ্য।", False, "It is a special provision for Assam.|ই অসমৰ বিশেষ ব্যৱস্থা।"),
   MA([("15 August 1985|১৫ আগষ্ট ১৯৮৫", "Assam Accord|অসম চুক্তি"), ("Section 6A|ধাৰা ৬ক", "Citizenship Act|নাগৰিকত্ব আইন"), ("25 March 1971|২৫ মাৰ্চ ১৯৭১", "Third period begins|তৃতীয় সময় আৰম্ভ")], "Keep event, section and date apart.|ঘটনা, ধাৰা আৰু তাৰিখ পৃথক ৰাখা।"),
   SP("Section *6B* implements the Assam Accord.|ধাৰা *৬খ-এ* অসম চুক্তি কাৰ্যকৰী কৰে।", "6A|৬ক-এ", "Section 6A is the 1985 provision; 6B is from 2019.|ধাৰা ৬ক ১৯৮৫ৰ; ৬খ ২০১৯ৰ।")),
 U(2, "scroll", "Two sections, two histories|দুটা ধাৰা, দুটা ইতিহাস", "Separate 6A, 6B and the court rulings.|ধাৰা ৬ক, ৬খ আৰু ৰায় পৃথক কৰা।",
   "Finding recorded: 6A was upheld in 2024; the challenge to the 2019 amendment is a separate case.|প্ৰমাণ লিখা হ'ল: ৬ক ২০২৪ত বৈধ বুলি কোৱা হ'ল; ২০১৯ৰ সংশোধনীৰ আপত্তি পৃথক গোচৰ।",
   ["On 17 October 2024 a Constitution Bench upheld Section 6A|২০২৪ৰ ১৭ অক্টোবৰত সাংবিধানিক বেঞ্চে ধাৰা ৬ক বৈধ বুলিলে", "The majority was 4 to 1|সংখ্যাগৰিষ্ঠতা ৪-১ আছিল", "The 2019 amendment added Section 6B|২০১৯ৰ সংশোধনীয়ে ধাৰা ৬খ যোগ কৰিলে", "Its cut-off is 31 December 2014|ইয়াৰ শেষ তাৰিখ ২০১৪ৰ ৩১ ডিচেম্বৰ"],
   S("Upheld, 4 to 1|বৈধ, ৪-১", "On <mark>17 October 2024</mark>, a Supreme Court Constitution Bench upheld Section 6A by a 4 to 1 majority.|<mark>২০২৪ৰ ১৭ অক্টোবৰত</mark> উচ্চতম ন্যায়ালয়ৰ সাংবিধানিক বেঞ্চে ৪-১ মতেৰে ধাৰা ৬ক বৈধ বুলিলে।", "The ruling was about that section's validity. It did not decide any person's citizenship.|ৰায়টো সেই ধাৰাৰ বৈধতাৰ বিষয়ে। ই কোনো ব্যক্তিৰ নাগৰিকত্ব ঠিক নকৰে।", art="court"),
   S("A different section|বেলেগ ধাৰা", "The <mark>2019 amendment</mark> added Section 6B for specified religious minorities from Afghanistan, Bangladesh and Pakistan who entered by <mark>31 December 2014</mark>, on conditions.|<mark>২০১৯ৰ সংশোধনীয়ে</mark> ধাৰা ৬খ যোগ কৰিলে। ই <mark>২০১৪ৰ ৩১ ডিচেম্বৰলৈ</mark> অহা আফগানিস্তান, বাংলাদেশ আৰু পাকিস্তানৰ নিৰ্দিষ্ট ধৰ্মীয় সংখ্যালঘুৰ বাবে, চৰ্ত সাপেক্ষে।", "Challenges to it were pending in the Supreme Court when this was written.|এই পাঠ লিখাৰ সময়ত ইয়াৰ বিৰুদ্ধে গোচৰ উচ্চতম ন্যায়ালয়ত বিচাৰাধীন আছিল।", art="scroll"),
   IN("Section 6A was upheld by a majority of|ধাৰা ৬ক বৈধ বুলি কোৱা সংখ্যাগৰিষ্ঠতা", ".|।", ["3 to 2|৩-২", "4 to 1|৪-১", "5 to 0|৫-০"], 1, "The Bench divided 4 to 1.|বেঞ্চ ৪-১ত বিভক্ত আছিল।"),
   TF("The 2024 ruling decided every challenge to the 2019 amendment.|২০২৪ৰ ৰায়ে ২০১৯ৰ সংশোধনীৰ সকলো আপত্তি মীমাংসা কৰিলে।", False, "It concerned Section 6A only.|ই কেৱল ধাৰা ৬ক-ৰ বিষয়ে।"),
   MA([("Section 6A|ধাৰা ৬ক", "Assam Accord, 1985|অসম চুক্তি, ১৯৮৫"), ("Section 6B|ধাৰা ৬খ", "2019 amendment|২০১৯ৰ সংশোধনী"), ("17 October 2024|১৭ অক্টোবৰ ২০২৪", "Section 6A upheld|ধাৰা ৬ক বৈধ")], "Two sections and one ruling.|দুটা ধাৰা আৰু এটা ৰায়।"),
   OD("Which date belongs to the 2019 amendment?|কোন তাৰিখ ২০১৯ৰ সংশোধনীৰ?", ["1 January 1966|১ জানুৱাৰী ১৯৬৬", "25 March 1971|২৫ মাৰ্চ ১৯৭১", "31 December 2014|৩১ ডিচেম্বৰ ২০১৪"], 2, "31 December 2014 is its cut-off.|২০১৪ৰ ৩১ ডিচেম্বৰ ইয়াৰ শেষ তাৰিখ।"),
   OR("Put these in order.|ক্ৰমত সজোৱা।", ["Assam Accord|অসম চুক্তি", "Citizenship amendment adding 6B|৬খ যোগ কৰা সংশোধনী", "Section 6A ruling|ধাৰা ৬ক-ৰ ৰায়"], "1985, 2019, 2024.|১৯৮৫, ২০১৯, ২০২৪।")),
]
t12 = TEST("Keep the dates and sections apart.|তাৰিখ আৰু ধাৰা পৃথক ৰাখা।", "Kept apart: each law has its own date and question.|পৃথক হ'ল: প্ৰতিখন আইনৰ নিজা তাৰিখ আৰু প্ৰশ্ন।",
   MA([("1 January 1966|১ জানুৱাৰী ১৯৬৬", "Section 6A boundary|ধাৰা ৬ক-ৰ সীমা"), ("31 December 2014|৩১ ডিচেম্বৰ ২০১৪", "Section 6B cut-off|ধাৰা ৬খ-ৰ শেষ তাৰিখ"), ("15 August 1985|১৫ আগষ্ট ১৯৮৫", "Accord signed|চুক্তি স্বাক্ষৰ")], "Three dates, three laws.|তিনিটা তাৰিখ, তিনিটা আইন।"),
   TF("Section 6A is a special provision for Assam.|ধাৰা ৬ক অসমৰ বিশেষ ব্যৱস্থা।", True, "It implements the Assam Accord.|ই অসম চুক্তি কাৰ্যকৰী কৰে।"),
   TF("A list or a date alone decides a person's citizenship.|কেৱল তালিকা বা তাৰিখে ব্যক্তিৰ নাগৰিকত্ব ঠিক কৰে।", False, "Individual status follows legal process.|ব্যক্তিৰ স্থিতি আইনী প্ৰক্ৰিয়াৰে ঠিক হয়।"),
   IN("The Supreme Court upheld Section 6A in|উচ্চতম ন্যায়ালয়ে ধাৰা ৬ক বৈধ বুলিলে", ".|চনত।", ["2019|২০১৯", "2024|২০২৪"], 1, "On 17 October 2024.|২০২৪ৰ ১৭ অক্টোবৰত।"),
   OD("Which is not part of the Section 6B countries?|ধাৰা ৬খ-ৰ দেশৰ মাজত কোনটো নাই?", ["Afghanistan|আফগানিস্তান", "Bangladesh|বাংলাদেশ", "Myanmar|ম্যানমাৰ", "Pakistan|পাকিস্তান"], 2, "The three are Afghanistan, Bangladesh and Pakistan.|তিনিখন আফগানিস্তান, বাংলাদেশ আৰু পাকিস্তান।"),
   OR("Put the Assam periods in order.|অসমৰ সময় ক্ৰমত সজোৱা।", ["Before 1966|১৯৬৬ৰ আগত", "1966 to March 1971|১৯৬৬ৰ পৰা মাৰ্চ ১৯৭১", "After 24 March 1971|১৯৭১ৰ ২৪ মাৰ্চৰ পিছত"], "Three periods.|তিনিটা সময়।"))
